INSERT INTO provider_profiles (id, user_id, business_name, slug, headline, bio, experience_years, city, service_area, approval_status, is_verified, approved_at, created_at) VALUES
(1, 11, 'Alex Plumbing', 'alex-plumbing', 'Licensed plumber for repairs, installations and emergencies', 'Hi, I''m Alex. I''ve been fixing leaks, unblocking drains and installing bathrooms across Prishtina for over 12 years. I arrive on time, explain the problem in plain words and leave your home clean. All work comes with a 6-month guarantee.', 12, 'Prishtina', 'Prishtina, Fushë Kosovë, Graçanica', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 364 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 365 DAY), '09:05:00')),
(2, 12, 'Pro Electric', 'pro-electric', 'Certified electricians for safe, tidy electrical work', 'Pro Electric is a small team of certified electricians. From a single faulty socket to a full panel upgrade, we work safely, to code, and we always test everything before we leave.', 9, 'Prishtina', 'Prishtina and surroundings (20 km)', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 349 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 350 DAY), '09:05:00')),
(3, 13, 'TechCare IT', 'techcare-it', 'Friendly IT support for homes and small businesses', 'TechCare IT helps families and small offices with slow computers, viruses, Wi-Fi dead zones and smart home gadgets. Many problems can be solved remotely the same day.', 7, 'Prizren', 'Prizren on-site, remote support everywhere', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 329 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 330 DAY), '09:05:00')),
(4, 14, 'CleanHome', 'cleanhome', 'Spotless homes with eco-friendly products', 'CleanHome brings a trained, insured cleaning team and all supplies. We use eco-friendly products that are safe for kids and pets, and we follow a detailed checklist on every visit.', 6, 'Prishtina', 'Prishtina, Fushë Kosovë', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 319 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 320 DAY), '09:05:00')),
(5, 15, 'AutoFix Garage', 'autofix-garage', 'Honest car servicing and repairs in Peja', 'AutoFix Garage is a family-run workshop with modern diagnostic equipment. We give you a clear quote before any work starts and we only use quality parts.', 15, 'Peja', 'Peja, Istog, Klina', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 299 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 300 DAY), '09:05:00')),
(6, 16, 'GardenPro', 'gardenpro', 'Beautiful, low-maintenance gardens all year round', 'GardenPro designs and maintains gardens of every size. Regular lawn care, hedge trimming or a full makeover — we bring our own tools and take the green waste away.', 8, 'Gjakova', 'Gjakova, Rahovec, Deçan', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 279 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 280 DAY), '09:05:00')),
(7, 17, 'QuickMove', 'quickmove', 'Stress-free moves with a careful crew and van', 'QuickMove handles apartment and house moves with a professional crew, a large van and protective materials. We disassemble, wrap, carry and reassemble — you just tell us where things go.', 5, 'Prishtina', 'Anywhere in Kosovo', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 269 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 270 DAY), '09:05:00')),
(8, 18, 'ColorCraft Painting', 'colorcraft-painting', 'Clean, precise painting for homes and businesses', 'ColorCraft protects your floors and furniture, repairs walls properly and delivers smooth, even finishes. Free colour advice included with every job.', 10, 'Ferizaj', 'Ferizaj, Shtime, Kaçanik', 'approved', 0, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 249 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 250 DAY), '09:05:00')),
(9, 19, 'FixIt Appliances', 'fixit-appliances', 'Fast repairs for all major appliance brands', 'FixIt Appliances repairs washing machines, fridges, dishwashers, ovens and air conditioners. We carry common spare parts in our van, so most repairs are finished on the first visit.', 11, 'Mitrovica', 'Mitrovica, Vushtrri, Skenderaj', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 239 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 240 DAY), '09:05:00')),
(10, 20, 'Glow Beauty Studio', 'glow-beauty-studio', 'Hair, nails and makeup in a calm studio', 'Glow Beauty Studio is a bright, relaxing space in the centre of Prishtina. Our licensed team specialises in modern cuts, gel nails and makeup for every occasion.', 7, 'Prishtina', 'Studio in Prishtina centre', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 229 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 230 DAY), '09:05:00')),
(11, 21, 'Lens & Light Studio', 'lens-and-light-studio', 'Natural, story-driven photography', 'I''m Rina, a photographer who loves natural light and real moments. Portraits, events and weddings — you receive a fully edited online gallery within one week.', 6, 'Prizren', 'Prizren and all of Kosovo', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 219 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 220 DAY), '09:05:00')),
(12, 22, 'Swift Plumbing Pros', 'swift-plumbing-pros', 'Quick-response plumbing in Prizren', 'Swift Plumbing Pros covers Prizren with fast response times for leaks, blocked drains and bathroom installations. Fair prices and no call-out fee within the city.', 4, 'Prizren', 'Prizren, Suhareka', 'approved', 0, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 199 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 200 DAY), '09:05:00')),
(13, 23, 'SparkHome Electric', 'sparkhome-electric', 'Residential electrical work in Prizren', 'SparkHome Electric is a new local electrical business focused on home repairs and lighting upgrades.', 3, 'Prizren', 'Prizren', 'pending', 0, NULL, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 4 DAY), '09:05:00')),
(14, 24, 'HandyHub', 'handyhub', 'Your go-to handyman for small jobs', 'HandyHub takes care of the small jobs that never get done: furniture assembly, TV mounting, shelves, doors and locks. One visit, many fixes.', 8, 'Prishtina', 'Prishtina, Obiliq, Lipjan', 'approved', 1, TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 189 DAY), '12:00:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 190 DAY), '09:05:00'));
