-- =====================================================================
--  LemboFix — database schema
--  MySQL 8+ / MariaDB 10.4+ · InnoDB · utf8mb4
--  Import this file in phpMyAdmin (Import tab) or run:
--     mysql -u root < database/schema.sql
--  Demo password for every seeded account:  Demo@1234
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `lembofix` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `lembofix`;

DROP TABLE IF EXISTS rate_limits, activity_logs, password_resets, reports, favorites, notifications,
    reviews, booking_items, bookings, time_off, availability, provider_services, provider_categories,
    services, categories, provider_profiles, customer_profiles, users;

-- ---------------------------------------------------------------------
--  Accounts
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    role            ENUM('customer','provider','admin') NOT NULL DEFAULT 'customer',
    first_name      VARCHAR(60)  NOT NULL,
    last_name       VARCHAR(60)  NOT NULL,
    email           VARCHAR(190) NOT NULL,
    password_hash   VARCHAR(255) NOT NULL,
    phone           VARCHAR(30)  NULL,
    city            VARCHAR(80)  NULL,
    avatar          VARCHAR(255) NULL,
    status          ENUM('active','suspended') NOT NULL DEFAULT 'active',
    last_login_at   DATETIME NULL,
    created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_role_status (role, status),
    KEY idx_users_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE customer_profiles (
    user_id           INT UNSIGNED PRIMARY KEY,
    address           VARCHAR(255) NULL,
    postal_code       VARCHAR(20)  NULL,
    preferred_contact ENUM('email','phone') NOT NULL DEFAULT 'email',
    created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_customer_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- avg_rating / review_count are a cache refreshed by the app whenever a review
-- changes (see refresh_provider_rating()); they keep search sorting fast.
CREATE TABLE provider_profiles (
    id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id          INT UNSIGNED NOT NULL,
    business_name    VARCHAR(120) NOT NULL,
    slug             VARCHAR(140) NOT NULL,
    headline         VARCHAR(160) NULL,
    bio              TEXT NULL,
    experience_years TINYINT UNSIGNED NOT NULL DEFAULT 0,
    city             VARCHAR(80)  NOT NULL,
    service_area     VARCHAR(160) NULL,
    address          VARCHAR(255) NULL,
    approval_status  ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
    rejection_reason VARCHAR(255) NULL,
    is_verified      TINYINT(1) NOT NULL DEFAULT 0,
    approved_at      DATETIME NULL,
    avg_rating       DECIMAL(3,2) NOT NULL DEFAULT 0.00,
    review_count     INT UNSIGNED NOT NULL DEFAULT 0,
    created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_provider_user (user_id),
    UNIQUE KEY uq_provider_slug (slug),
    KEY idx_provider_status_city (approval_status, city),
    KEY idx_provider_rating (avg_rating),
    CONSTRAINT fk_provider_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  Catalog
-- ---------------------------------------------------------------------
CREATE TABLE categories (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(80)  NOT NULL,
    slug        VARCHAR(90)  NOT NULL,
    icon        VARCHAR(40)  NOT NULL DEFAULT 'wrench',
    description VARCHAR(255) NULL,
    sort_order  SMALLINT NOT NULL DEFAULT 0,
    is_active   TINYINT(1) NOT NULL DEFAULT 1,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_categories_name (name),
    UNIQUE KEY uq_categories_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Platform-wide service types (e.g. "Leak Repair" in Plumbing)
CREATE TABLE services (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    category_id INT UNSIGNED NOT NULL,
    name        VARCHAR(120) NOT NULL,
    slug        VARCHAR(140) NOT NULL,
    description VARCHAR(255) NULL,
    is_active   TINYINT(1) NOT NULL DEFAULT 1,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_services_slug (slug),
    UNIQUE KEY uq_services_cat_name (category_id, name),
    CONSTRAINT fk_services_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE provider_categories (
    provider_id INT UNSIGNED NOT NULL,
    category_id INT UNSIGNED NOT NULL,
    PRIMARY KEY (provider_id, category_id),
    KEY idx_pc_category (category_id),
    CONSTRAINT fk_pc_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE CASCADE,
    CONSTRAINT fk_pc_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- What a provider actually sells: their own title, price and duration for a service type
CREATE TABLE provider_services (
    id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    provider_id      INT UNSIGNED NOT NULL,
    service_id       INT UNSIGNED NOT NULL,
    title            VARCHAR(140) NOT NULL,
    description      TEXT NULL,
    price            DECIMAL(10,2) NOT NULL,
    price_type       ENUM('fixed','hourly','from') NOT NULL DEFAULT 'fixed',
    duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 60,
    location_type    ENUM('customer','provider','remote') NOT NULL DEFAULT 'customer',
    is_active        TINYINT(1) NOT NULL DEFAULT 1,
    created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_ps_provider (provider_id, is_active),
    KEY idx_ps_service (service_id),
    KEY idx_ps_price (price),
    CONSTRAINT fk_ps_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE CASCADE,
    CONSTRAINT fk_ps_service  FOREIGN KEY (service_id)  REFERENCES services(id) ON DELETE RESTRICT,
    CONSTRAINT chk_ps_price    CHECK (price >= 0),
    CONSTRAINT chk_ps_duration CHECK (duration_minutes BETWEEN 15 AND 720)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  Availability
-- ---------------------------------------------------------------------
-- One row per weekday (0 = Sunday … 6 = Saturday)
CREATE TABLE availability (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    provider_id INT UNSIGNED NOT NULL,
    day_of_week TINYINT UNSIGNED NOT NULL,
    is_working  TINYINT(1) NOT NULL DEFAULT 1,
    start_time  TIME NOT NULL DEFAULT '09:00:00',
    end_time    TIME NOT NULL DEFAULT '17:00:00',
    break_start TIME NULL,
    break_end   TIME NULL,
    UNIQUE KEY uq_availability_day (provider_id, day_of_week),
    CONSTRAINT fk_availability_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE CASCADE,
    CONSTRAINT chk_availability_dow CHECK (day_of_week BETWEEN 0 AND 6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Days off and vacations (inclusive date ranges)
CREATE TABLE time_off (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    provider_id INT UNSIGNED NOT NULL,
    start_date  DATE NOT NULL,
    end_date    DATE NOT NULL,
    type        ENUM('day_off','vacation') NOT NULL DEFAULT 'day_off',
    reason      VARCHAR(160) NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_time_off_range (provider_id, start_date, end_date),
    CONSTRAINT fk_time_off_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE CASCADE,
    CONSTRAINT chk_time_off_range CHECK (end_date >= start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  Bookings
-- ---------------------------------------------------------------------
CREATE TABLE bookings (
    id                  INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    reference           VARCHAR(16) NOT NULL,
    customer_id         INT UNSIGNED NOT NULL,
    provider_id         INT UNSIGNED NOT NULL,
    booking_date        DATE NOT NULL,
    start_time          TIME NOT NULL,
    end_time            TIME NOT NULL,
    address             VARCHAR(255) NOT NULL,
    city                VARCHAR(80)  NOT NULL,
    customer_message    TEXT NULL,
    status              ENUM('pending','confirmed','rejected','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',
    subtotal            DECIMAL(10,2) NOT NULL,
    platform_fee        DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    total               DECIMAL(10,2) NOT NULL,
    payment_method      ENUM('card','cash') NOT NULL DEFAULT 'cash',
    payment_status      ENUM('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid',
    provider_note       VARCHAR(255) NULL,
    cancelled_by        ENUM('customer','provider','admin') NULL,
    cancellation_reason VARCHAR(255) NULL,
    reminder_sent_at    DATETIME NULL,
    confirmed_at        DATETIME NULL,
    completed_at        DATETIME NULL,
    cancelled_at        DATETIME NULL,
    created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_bookings_reference (reference),
    KEY idx_bookings_provider_date (provider_id, booking_date, status),
    KEY idx_bookings_customer (customer_id, status),
    KEY idx_bookings_status (status, booking_date),
    CONSTRAINT fk_bookings_customer FOREIGN KEY (customer_id) REFERENCES users(id) ON DELETE RESTRICT,
    CONSTRAINT fk_bookings_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE RESTRICT,
    CONSTRAINT chk_bookings_time CHECK (end_time > start_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Snapshot of each booked service (title/price at booking time)
CREATE TABLE booking_items (
    id                  INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    booking_id          INT UNSIGNED NOT NULL,
    provider_service_id INT UNSIGNED NULL,
    title               VARCHAR(140) NOT NULL,
    price               DECIMAL(10,2) NOT NULL,
    duration_minutes    SMALLINT UNSIGNED NOT NULL,
    KEY idx_bi_booking (booking_id),
    KEY idx_bi_service (provider_service_id),
    CONSTRAINT fk_bi_booking FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE,
    CONSTRAINT fk_bi_service FOREIGN KEY (provider_service_id) REFERENCES provider_services(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  Reviews (one per completed booking; provider & customer come from the booking)
-- ---------------------------------------------------------------------
CREATE TABLE reviews (
    id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    booking_id     INT UNSIGNED NOT NULL,
    rating         TINYINT UNSIGNED NOT NULL,
    comment        TEXT NOT NULL,
    provider_reply TEXT NULL,
    replied_at     DATETIME NULL,
    status         ENUM('published','hidden') NOT NULL DEFAULT 'published',
    created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_reviews_booking (booking_id),
    KEY idx_reviews_status (status, created_at),
    CONSTRAINT fk_reviews_booking FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE,
    CONSTRAINT chk_reviews_rating CHECK (rating BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  Engagement
-- ---------------------------------------------------------------------
CREATE TABLE favorites (
    customer_id INT UNSIGNED NOT NULL,
    provider_id INT UNSIGNED NOT NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (customer_id, provider_id),
    KEY idx_favorites_provider (provider_id),
    CONSTRAINT fk_fav_customer FOREIGN KEY (customer_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_fav_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE notifications (
    id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id    INT UNSIGNED NOT NULL,
    type       VARCHAR(40)  NOT NULL,
    title      VARCHAR(140) NOT NULL,
    message    VARCHAR(255) NOT NULL,
    link       VARCHAR(255) NULL,
    is_read    TINYINT(1) NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_notifications_user (user_id, is_read, created_at),
    CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE reports (
    id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    reporter_id INT UNSIGNED NULL,
    review_id   INT UNSIGNED NULL,
    provider_id INT UNSIGNED NULL,
    reason      ENUM('spam','offensive','fake','inappropriate','other') NOT NULL,
    details     VARCHAR(500) NULL,
    status      ENUM('open','resolved','dismissed') NOT NULL DEFAULT 'open',
    admin_note  VARCHAR(255) NULL,
    resolved_by INT UNSIGNED NULL,
    resolved_at DATETIME NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_reports_status (status, created_at),
    CONSTRAINT fk_reports_reporter FOREIGN KEY (reporter_id) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT fk_reports_review   FOREIGN KEY (review_id)   REFERENCES reviews(id) ON DELETE CASCADE,
    CONSTRAINT fk_reports_provider FOREIGN KEY (provider_id) REFERENCES provider_profiles(id) ON DELETE CASCADE,
    CONSTRAINT fk_reports_resolver FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  Security & auditing
-- ---------------------------------------------------------------------
CREATE TABLE password_resets (
    id         INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id    INT UNSIGNED NOT NULL,
    token_hash CHAR(64) NOT NULL,
    expires_at DATETIME NOT NULL,
    used_at    DATETIME NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_password_resets_token (token_hash),
    KEY idx_password_resets_user (user_id),
    CONSTRAINT fk_password_resets_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE activity_logs (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    user_id     INT UNSIGNED NULL,
    action      VARCHAR(60) NOT NULL,
    entity_type VARCHAR(40) NULL,
    entity_id   INT UNSIGNED NULL,
    description VARCHAR(255) NOT NULL,
    ip_address  VARCHAR(45) NULL,
    created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_activity_created (created_at),
    KEY idx_activity_user (user_id),
    CONSTRAINT fk_activity_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Sliding-window counters for login throttling and LemboBot usage limits
CREATE TABLE rate_limits (
    id         BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    bucket     VARCHAR(40)  NOT NULL,
    identifier VARCHAR(120) NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_rate_limits_lookup (bucket, identifier, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
-- ---------------------------------------------------------------------
--  Demo data
-- ---------------------------------------------------------------------















-- Refresh cached rating aggregates
UPDATE provider_profiles p SET
  avg_rating = COALESCE((SELECT ROUND(AVG(r.rating), 2) FROM reviews r JOIN bookings b ON b.id = r.booking_id WHERE b.provider_id = p.id AND r.status = 'published'), 0),
  review_count = (SELECT COUNT(*) FROM reviews r JOIN bookings b ON b.id = r.booking_id WHERE b.provider_id = p.id AND r.status = 'published');





